        console.log(`\n🚨 BUG FOUND @ Month ${state.currentMonth}: structuredClone NOT cloning techTreeState!`);
        console.log(`   techTreeState is the SAME object in clone (not a deep copy)`);
        console.log(`   This means all snapshots share the same techTreeState object!`);

