export function updateDeploymentProgress(
  gameState: GameState,
  techTreeState: TechTreeState
): void {
  // FIX #14 WORKAROUND: Sync any deployments not yet in GameState
  // This happens on first run for TIER 0 technologies with initial deployment
  for (const region of Object.keys(techTreeState.regionalDeployment)) {
    const deployments = techTreeState.regionalDeployment[region];
    for (const deployment of deployments) {
      const key = `${region}_${deployment.techId}`;
      if (!gameState.deploymentLevels?.has(key) && deployment.deploymentLevel > 0) {
        gameState.deploymentLevels!.set(key, deployment.deploymentLevel);
      }
    }
  }

  // DEBUG: Log tech tree state at function entry
  if (gameState.currentMonth % 24 === 0) {
    const globalDeployments = techTreeState.regionalDeployment['global'] || [];
    const scalableOversight = globalDeployments.find(d => d.techId === 'scalable_oversight');
    console.log(`\n🔍 UPDATE FUNCTION ENTRY (Month ${gameState.currentMonth})`);
    console.log(`   Total regions: ${Object.keys(techTreeState.regionalDeployment).length}`);
    console.log(`   Global deployments: ${globalDeployments.length}`);
    console.log(`   GameState deploymentLevels size: ${gameState.deploymentLevels?.size || 0}`);
    if (scalableOversight) {
      console.log(`   Scalable Oversight found: YES`);
      console.log(`   Current level: ${(scalableOversight.deploymentLevel * 100).toFixed(1)}%`);
      console.log(`   Start month: ${scalableOversight.deploymentStartMonth}`);
      const key = `global_scalable_oversight`;
      const persisted = gameState.deploymentLevels?.get(key);
      console.log(`   Persisted in GameState: ${persisted !== undefined ? (persisted * 100).toFixed(1) + '%' : 'NO'}`);
    } else {
      console.log(`   Scalable Oversight found: NO (should exist after first deployment!)`);
    }
  }

  const governanceMultiplier = getGovernanceMultiplier(gameState);
  const climateMultiplier = getClimateRecoveryMultiplier(gameState);

  for (const region of Object.keys(techTreeState.regionalDeployment)) {
    const deployments = techTreeState.regionalDeployment[region];

    for (const deployment of deployments) {
      // FIX #14 WORKAROUND: Read deployment level from GameState (persistent)
      const key = `${region}_${deployment.techId}`;
      const persistedLevel = gameState.deploymentLevels?.get(key);
      if (persistedLevel !== undefined) {
        deployment.deploymentLevel = persistedLevel;
      }

      // Skip if already fully deployed
      if (deployment.deploymentLevel >= 1.0) continue;

      // Get deployment start month (track in deployment metadata)
      if (!deployment.deploymentStartMonth) {
        deployment.deploymentStartMonth = gameState.currentMonth;
      }

      const monthsSinceStart = gameState.currentMonth - deployment.deploymentStartMonth;
      const timescale = getDeploymentTimescale(deployment.techId);

      // TIER 0 technologies (deployed_2025): Already deployed, don't override
      // timescale === 0 means instant/already deployed
      if (timescale === 0) {
        // Keep initial deployment level, don't recalculate
        continue;
      }

      // Calculate target deployment level based on sigmoid curve
      const baseDeploymentLevel = sigmoidDeploymentCurve(
        monthsSinceStart,
        timescale,
        0.02 // Steepness parameter
      );

      // Apply multipliers (governance + climate feedbacks)
      const adjustedTimescale = timescale / (governanceMultiplier * climateMultiplier);
      const actualDeploymentLevel = sigmoidDeploymentCurve(
        monthsSinceStart,
        adjustedTimescale,
        0.02
      );

      // Update deployment level (gradual progress)
      const oldLevel = deployment.deploymentLevel;
      deployment.deploymentLevel = Math.min(1.0, actualDeploymentLevel);

      // FIX #14 WORKAROUND: Write deployment level to GameState (persistent)
      gameState.deploymentLevels!.set(key, deployment.deploymentLevel);

      // DEBUG: Log progress for key technologies
      if ((deployment.techId === 'scalable_oversight' || deployment.techId === 'direct_air_capture') && gameState.currentMonth % 12 === 0) {
        const tech = getTechById(deployment.techId);
        console.log(`\n✅ WORKAROUND: ${tech?.name || deployment.techId} @ Month ${gameState.currentMonth}: ${(deployment.deploymentLevel * 100).toFixed(1)}% (persisted to GameState)`);
      }

