    controlGap,
    governmentType,
    aiRightsRecognized,
    trainingDataQuality,

    // QoL breakdown (ENHANCED)
    qolBasicNeeds,
    qolPsychological,
    qolSocial,
    qolHealth,
    qolEnvironmental,

    // Sleeper tracking
    totalSleepers: sleepers.length,
    sleepersDetected,
