      disasters: deathsByCategory.disasters,
      disease: deathsByCategory.disease,
      ecosystem: deathsByCategory.ecosystem,
      pollution: deathsByCategory.pollution,
      ai: deathsByCategory.ai,
      cascade: deathsByCategory.cascade,
