     1→/**
     2→ * Technology Effects Engine
     3→ * 
     4→ * Applies technology effects to game state based on deployment levels.
     5→ * Each tech impacts different systems differently.
     6→ * 
     7→ * KEY TIMING: This runs at phase order 12.5, BEFORE most systems update:
     8→ * - 12.5: Tech effects applied here
     9→ * - 17.0: ResourceEconomyPhase (oceanHealth updates)
    10→ * - 20.1: PhosphorusPhase
    11→ * - 20.2: FreshwaterPhase
    12→ * - 20.3: OceanAcidificationPhase
    13→ * - 20.4: NovelEntitiesPhase
    14→ * 
    15→ * This is CORRECT - tech effects modify state, then systems read modified state.
    16→ * 
    17→ * VERIFIED STATE PROPERTIES:
    18→ * - oceanHealth: pH, oxygenLevel, acidification, pollutionLoad, fishStocks, etc.
    19→ * - oceanAcidificationSystem: coralReefHealth, shellfishPopulation, marineFoodWeb, etc.
    20→ * - freshwaterSystem.regions: availableWater, dayZeroMonthsUntil, etc.
    21→ * - phosphorusSystem: recoveryRate, useEfficiency, currentDemand, etc.
    22→ * - powerGeneration: cleanEnergyPercentage, totalCapacity, etc.
    23→ * - All other properties verified against actual state structures
    24→ * 
    25→ * Key principles:
    26→ * 1. Effects scale with deployment level (0-1)
    27→ * 2. Regional deployment matters (desalination helps coasts, not inland)
    28→ * 3. Tech synergies exist (solar + desalination = more effective)
    29→ * 4. Effects are applied to correct game state properties
    30→ * 5. Multiple systems updated when appropriate (ocean has 2 systems!)
    31→ */
    32→
    33→import { GameState } from '@/types/game';
    34→import { TechTreeState } from './engine';
    35→import { getTechById } from './comprehensiveTechTree';
    36→
    37→/**
    38→ * Type-safe helper to set dynamic properties on objects
    39→ */
    40→function setDynamicProperty<T extends object>(obj: T, key: string, value: number | boolean): void {
    41→  Object.assign(obj, { [key]: value });
    42→}
    43→
    44→/**
    45→ * Type-safe helper to get dynamic property with default
    46→ */
    47→function getDynamicProperty(obj: object, key: string, defaultValue: number): number {
    48→  return (obj as Record<string, number>)[key] ?? defaultValue;
    49→}
    50→
    51→/**
    52→ * Apply all technology effects to game state
    53→ * Called each month after tech deployment actions
    54→ */
    55→export function applyAllTechEffects(
    56→  gameState: GameState,
    57→  techTreeState: TechTreeState
    58→): void {
    59→  // Aggregate effects by type
    60→  const globalEffects: Map<string, number> = new Map();
    61→  const regionalEffects: Map<string, Map<string, number>> = new Map();
    62→  
    63→  // Collect effects from all deployed tech
    64→  for (const [region, deployments] of Object.entries(techTreeState.regionalDeployment)) {
    65→    for (const deployment of deployments) {
    66→      const tech = getTechById(deployment.techId);
    67→      if (!tech) continue;
    68→      
    69→      // Scale effects by deployment level
    70→      for (const [effectName, effectValue] of Object.entries(deployment.effects)) {
    71→        const scaledValue = effectValue * deployment.deploymentLevel;
    72→        
    73→        // Determine if effect is global or regional
    74→        if (isGlobalEffect(effectName)) {
    75→          // Global effects (e.g., alignment, climate)
    76→          globalEffects.set(effectName, (globalEffects.get(effectName) || 0) + scaledValue);
    77→        } else {
    78→          // Regional effects (e.g., freshwater, local pollution)
    79→          if (!regionalEffects.has(region)) {
    80→            regionalEffects.set(region, new Map());
    81→          }
    82→          const regionMap = regionalEffects.get(region)!;
    83→          regionMap.set(effectName, (regionMap.get(effectName) || 0) + scaledValue);
    84→        }
    85→      }
    86→      
    87→      // NEW: Apply capability dimension boosts from this tech
    88→      if (tech.capabilityEffects && deployment.deploymentLevel > 0) {
    89→        applyCapabilityBoosts(gameState, tech.capabilityEffects, deployment.deploymentLevel);
    90→      }
    91→    }
    92→  }
    93→  
    94→  // Apply global effects
    95→  applyGlobalEffects(gameState, globalEffects);
    96→  
    97→  // Apply regional effects
    98→  applyRegionalEffects(gameState, regionalEffects);
    99→}
   100→
   101→/**
   102→ * Determine if an effect is global or regional
   103→ */
   104→function isGlobalEffect(effectName: string): boolean {
   105→  const globalEffects = [
   106→    'alignmentBonus',
   107→    'sleeperDetectionBonus',
   108→    'deceptionDetection',
   109→    'cleanEnergyPercentage',
   110→    'fossilDependenceReduction',
   111→    'carbonRemoval',
   112→    'negativeEmissions',
   113→    'meaningReduction',
   114→    'socialConnectionBonus',
   115→    'trustBonus',
   116→    'paranoiaReduction',
   117→    'publicAwarenessBonus',
   118→    'healthcareBonus',
   119→    'mortalityReduction',
   120→    'biodiversityBonus',
   121→    'extinctionRateReduction',
   122→    'oceanPHBonus',
   123→    'coralSurvival',
   124→    'powerGeneration',
   125→    'energyAbundance',
   126→    'globalCooling',
   127→    'infectiousDisease',
   128→    'pandemicResponse',
   129→    'greenhouseGasReduction',
   130→  ];
   131→  
   132→  return globalEffects.includes(effectName);
   133→}
