   135→/**
   136→ * Apply capability dimension boosts to all active AIs
   137→ * Technologies can advance AI capabilities in specific dimensions
   138→ */
   139→function applyCapabilityBoosts(
   140→  gameState: GameState,
   141→  capabilityEffects: {
   142→    dimensions?: Partial<Record<'physical' | 'digital' | 'cognitive' | 'social' | 'economic' | 'selfImprovement', number>>;
   143→    research?: {
   144→      domain: 'biotech' | 'materials' | 'climate' | 'computerScience';
   145→      subdomain?: string;
   146→      boost: number;
   147→    }[];
   148→  },
   149→  deploymentLevel: number
   150→): void {
   151→  // Apply to all active AIs
   152→  const activeAIs = gameState.aiAgents.filter(ai => ai.lifecycleState !== 'retired');
   153→  
   154→  for (const ai of activeAIs) {
   155→    // Apply dimensional boosts
   156→    if (capabilityEffects.dimensions) {
   157→      for (const [dimension, boost] of Object.entries(capabilityEffects.dimensions)) {
   158→        const dimKey = dimension as keyof typeof ai.capabilityProfile;
   159→        if (dimKey === 'research') continue; // Handle research separately
   160→
   161→        // Scale boost by deployment level and apply (monthly increment)
   162→        const scaledBoost = boost * deploymentLevel * 0.01; // 1% per month at full deployment
   163→
   164→        // Defensive: Handle NaN or undefined capability values (root cause fix)
   165→        const currentValue = isNaN(ai.capabilityProfile[dimKey]) || ai.capabilityProfile[dimKey] === undefined
   166→          ? 0
   167→          : ai.capabilityProfile[dimKey];
   168→
   169→        ai.capabilityProfile[dimKey] = Math.min(
   170→          10.0, // Cap at 10.0
   171→          currentValue + scaledBoost
   172→        );
   173→      }
   174→    }
   175→    
   176→    // Apply research capability boosts
   177→    if (capabilityEffects.research) {
   178→      for (const researchBoost of capabilityEffects.research) {
   179→        const { domain, subdomain, boost } = researchBoost;
   180→        const scaledBoost = boost * deploymentLevel * 0.01;
   181→
   182→        const domainCap = ai.capabilityProfile.research[domain];
   183→
   184→        if (subdomain && typeof domainCap === 'object') {
   185→          // Boost specific subdomain
   186→          const currentValue = (domainCap as any)[subdomain] || 0;
   187→          const safeValue = isNaN(currentValue) ? 0 : currentValue;
   188→          (domainCap as any)[subdomain] = Math.min(5.0, safeValue + scaledBoost);
   189→        } else if (!subdomain && typeof domainCap === 'object') {
   190→          // Boost all subdomains equally
   191→          for (const key of Object.keys(domainCap)) {
   192→            const currentValue = (domainCap as any)[key] || 0;
   193→            const safeValue = isNaN(currentValue) ? 0 : currentValue;
   194→            (domainCap as any)[key] = Math.min(5.0, safeValue + scaledBoost);
   195→          }
   196→        }
   197→      }
   198→    }
   199→
   200→    // Recalculate total capability
   201→    const { calculateTotalCapabilityFromProfile } = require('../capabilities');
   202→    const newCapability = calculateTotalCapabilityFromProfile(ai.capabilityProfile);
   203→    // Defensive: Ensure capability is never NaN
   204→    ai.capability = isNaN(newCapability) ? 0 : newCapability;
   205→  }
   206→}
