   208→/**
   209→ * Apply global effects to game state
   210→ */
   211→function applyGlobalEffects(
   212→  gameState: GameState,
   213→  effects: Map<string, number>
   214→): void {
   215→  for (const [effectName, value] of effects) {
   216→    switch (effectName) {
