   222→            ai.alignment = Math.min(1.0, ai.alignment + value * 0.01); // Per month
   223→          }
   224→        }
   225→        break;
   226→        
   227→      case 'sleeperDetectionBonus':
   228→        // Improve defensive AI detection
   229→        if (gameState.defensiveAI) {
   230→          gameState.defensiveAI.threatDetection.detectSleepers = Math.min(
   231→            1.0,
   232→            (gameState.defensiveAI.threatDetection.detectSleepers || 0) + value
   233→          );
   234→        }
   235→        break;
   236→        
   237→      case 'deceptionDetection':
   238→        // Improve ability to detect deceptive AIs
   239→        if (gameState.defensiveAI) {
   240→          gameState.defensiveAI.threatDetection.detectDeception = Math.min(
   241→            1.0,
   242→            (gameState.defensiveAI.threatDetection.detectDeception || 0) + value
   243→          );
   244→        }
   245→        break;
   246→        
   247→      case 'threatContainment':
   248→        // Improve containment capabilities
   249→        if (gameState.defensiveAI) {
   250→          gameState.defensiveAI.containmentCapability = Math.min(
   251→            1.0,
   252→            (gameState.defensiveAI.containmentCapability || 0) + value
   253→          );
   254→        }
   255→        break;
   256→        
   257→      // ========== ENERGY ==========
   258→      case 'cleanEnergyPercentage':
   259→        // Increase clean energy share
   260→        if (gameState.powerGeneration) {
   261→          gameState.powerGeneration.cleanEnergyPercentage = Math.min(
   262→            1.0,
   263→            gameState.powerGeneration.cleanEnergyPercentage + value
   264→          );
   265→        }
   266→        break;
   267→        
   268→      case 'fossilDependenceReduction':
