   349→            gameState.ubiSystem.purposeInfrastructure.socialConnection + value * 0.01
   350→          );
   351→        }
   352→        break;
   353→        
   354→      case 'trustBonus':
   355→        // Increase public trust
   356→        if (gameState.globalMetrics) {
   357→          gameState.globalMetrics.publicTrust = Math.min(
   358→            1.0,
   359→            (gameState.globalMetrics.publicTrust || 0.5) + value * 0.01
