   532→              gameState.planetaryBoundaries.novelEntities - value * 0.01
   533→            );
   534→          }
   535→          break;
   536→          
   537→        case 'pfasReduction':
   538→          // Reduce PFAS contamination
   539→          if (gameState.planetaryBoundaries) {
   540→            (gameState.planetaryBoundaries as any).pfasContamination = Math.max(
