   549→          if (gameState.planetaryBoundaries) {
   550→            (gameState.planetaryBoundaries as any).plasticPollution = Math.max(
   551→              0,
   552→              ((gameState.planetaryBoundaries as any).plasticPollution || 0.6) - value * 0.01
   553→            );
   554→          }
