          break;

        case 'fisheryBonus':
          // Improve fish stocks
          if (gameState.oceanHealth) {
            gameState.oceanHealth.fishStocks = Math.min(
              1.0,
              gameState.oceanHealth.fishStocks + value * 0.01
            );
          }
          if (gameState.oceanAcidificationSystem) {
