          }
          break;

        case 'marineLifeBonus':
          // Improve phytoplankton and marine food web
          if (gameState.oceanHealth) {
            gameState.oceanHealth.phytoplanktonPopulation = Math.min(
              1.0,
              gameState.oceanHealth.phytoplanktonPopulation + value * 0.01
