          }
          break;

        // ========== ENERGY SYSTEMS ==========
        case 'energyStorageBonus':
          // Improve grid energy storage
          if (gameState.powerGeneration) {
            (gameState.powerGeneration as any).storageCapacity = 
              ((gameState.powerGeneration as any).storageCapacity || 1.0) * (1 + value * 0.01);
