    20→export const SOCIETY_ACTIONS: GameAction[] = [
    21→  {
    22→    id: 'adapt_social_norms',
    23→    name: 'Adapt Social Norms',
    24→    description: 'Different population segments adapt to post-AI world',
    25→    agentType: 'society',
    26→    energyCost: 1,
    27→    
    28→    canExecute: (state) => {
    29→      return state.society.socialAdaptation < 0.9;
    30→    },
    31→    
    32→    execute: (state, agentId, random = Math.random) => {
    33→      const economicStage = Math.floor(state.globalMetrics.economicTransitionStage);
    34→      const unemploymentLevel = state.society.unemploymentLevel;
    35→      const trustLevel = getTrustInAI(state.society); // Phase 2C: Use paranoia-derived trust
    36→      const hasUBI = state.government.activeRegulations.some(reg => reg.includes('UBI'));
    37→      const hasRetraining = state.government.activeRegulations.some(reg =>
    38→        reg.includes('Retraining') || reg.includes('Training')
    39→      );
    40→      const baseRate = state.config.socialAdaptationRate || 1.0;
    41→
    42→      // Quartile-based adaptation with realistic time horizons
    43→      let earlyAdopterGain = 0;
    44→      let mediumAdopterGain = 0;
    45→      let slowAdopterGain = 0;
    46→      let resistantAdopterGain = 0;
    47→
    48→      // Q1: Early Adopters (adapt in 6-12 months)
    49→      if (unemploymentLevel > 0.2 || economicStage >= 1) {
    50→        const monthlyRate = baseRate * 0.08;
    51→        earlyAdopterGain = Math.min(1.0 - state.society.earlyAdopters,
    52→          monthlyRate + (trustLevel * 0.02));
    53→      }
    54→
    55→      // Q2: Medium Adopters (2-5 year horizon)
    56→      if (unemploymentLevel > 0.4 || (economicStage >= 2 && hasUBI)) {
    57→        const monthlyRate = baseRate * 0.015;
    58→        const policyBonus = hasUBI ? 0.01 : 0;
    59→        mediumAdopterGain = Math.min(1.0 - state.society.mediumAdopters,
    60→          monthlyRate + policyBonus);
    61→      }
    62→
    63→      // Q3: Slow Adopters (decade horizon)
    64→      if (unemploymentLevel > 0.6 || (economicStage >= 3 && hasUBI)) {
    65→        const monthlyRate = baseRate * 0.006;
    66→        const crisisBonus = unemploymentLevel > 0.7 ? 0.003 : 0;
    67→        slowAdopterGain = Math.min(1.0 - state.society.slowAdopters,
    68→          monthlyRate + crisisBonus);
    69→      }
    70→
    71→      // Q4: Resistant Adopters (may never adapt)
    72→      if (unemploymentLevel > 0.8 && economicStage >= 3 && hasUBI && trustLevel > 0.6) {
    73→        const monthlyRate = baseRate * 0.002;
    74→        resistantAdopterGain = Math.min(1.0 - state.society.resistantAdopters, monthlyRate);
    75→      }
    76→
    77→      // Update quartile adoption levels
    78→      state.society.earlyAdopters = Math.min(1.0,
    79→        state.society.earlyAdopters + earlyAdopterGain);
    80→      state.society.mediumAdopters = Math.min(1.0,
    81→        state.society.mediumAdopters + mediumAdopterGain);
    82→      state.society.slowAdopters = Math.min(1.0,
    83→        state.society.slowAdopters + slowAdopterGain);
    84→      state.society.resistantAdopters = Math.min(1.0,
    85→        state.society.resistantAdopters + resistantAdopterGain);
    86→
    87→      // Overall social adaptation is weighted average
    88→      const newSocialAdaptation = (
    89→        state.society.earlyAdopters * 0.25 +
    90→        state.society.mediumAdopters * 0.25 +
    91→        state.society.slowAdopters * 0.25 +
    92→        state.society.resistantAdopters * 0.25
    93→      );
    94→
    95→      const adaptationGain = newSocialAdaptation - state.society.socialAdaptation;
    96→      state.society.socialAdaptation = newSocialAdaptation;
    97→
    98→      // Stability gain when multiple quartiles are adapting
    99→      const stabilityGain = adaptationGain * (economicStage >= 3 ? 1.5 : 0.5);
   100→      state.globalMetrics.socialStability += stabilityGain;
   101→
   102→      const adaptedQuartiles = [
   103→        state.society.earlyAdopters > 0.1 ? 'early adopters' : '',
   104→        state.society.mediumAdopters > 0.1 ? 'mainstream' : '',
   105→        state.society.slowAdopters > 0.1 ? 'traditionalists' : '',
   106→        state.society.resistantAdopters > 0.1 ? 'resisters' : ''
   107→      ].filter(Boolean);
   108→
   109→      return {
   110→        success: true,
   111→        effects: {
   112→          social_adaptation: adaptationGain,
