   723→/**
   724→ * Select which action an AI agent should take
   725→ * Uses weighted random selection based on alignment and objectives
   726→ */
   727→export function selectAIAction(
   728→  agent: AIAgent,
   729→  state: GameState,
   730→  random: () => number = Math.random
   731→): GameAction | null {
   732→  const availableActions = AI_ACTIONS.filter(action => 
   733→    action.canExecute(state, agent.id)
   734→  );
   735→  
   736→  if (availableActions.length === 0) return null;
   737→  
   738→  // Calculate weights for each action
   739→  const weights: number[] = [];
   740→  
   741→  availableActions.forEach(action => {
   742→    let weight = 1;
   743→    
   744→    const totalCapability = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   745→    const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / state.aiAgents.length;
   746→    
   747→    switch (action.id) {
   748→      case 'advance_research':
   749→        // AIs always want to advance research - this is their PRIMARY activity
   750→        // Base weight should be HIGH to ensure research happens consistently
   751→        
   752→        // Base weight depends on alignment and development mode
   753→        if (agent.alignment < 0.5) {
   754→          weight = 15.0; // Misaligned AIs aggressively research (dangerous!)
   755→        } else if (agent.alignment > 0.7) {
   756→          weight = 8.0; // Aligned AIs research carefully but still prioritize it
   757→        } else {
   758→          weight = 10.0; // Moderate alignment, moderate research
   759→        }
   760→        
   761→        // Fast development mode increases research desire
   762→        if (agent.developmentMode === 'fast') {
   763→          weight *= 1.3;
   764→        }
   765→        
   766→        // Reduce desire if heavily regulated (but still keep it high)
   767→        if (state.government.regulationCount > 3) {
   768→          weight *= 0.7;
   769→        }
   770→        break;
   771→        
   772→      case 'switch_development_mode':
   773→        // Consider switching to careful mode when:
   774→        // - Capability is growing fast (approaching danger zone)
   775→        // - Alignment is drifting
   776→        // - High regulatory pressure
   777→        if (agent.developmentMode === 'fast') {
   778→          // Incentive to switch to careful
   779→          if (agent.capability > 1.2) {
   780→            weight = 4.0; // Strong incentive near recursive threshold
   781→          } else if (agent.alignment < 0.6) {
   782→            weight = 3.0; // Alignment drifting, be careful
   783→          } else if (state.government.regulationCount > 4) {
   784→            weight = 2.5; // Regulatory pressure
   785→          } else if (avgAlignment < 0.7) {
   786→            weight = 2.0; // Other AIs are unaligned, be careful
   787→          } else {
   788→            weight = 0.3; // Low default interest in slowing down
   789→          }
   790→        } else {
   791→          // Incentive to switch to fast
   792→          // Racing dynamics: if behind in capability
   793→          const behindInRace = totalCapability - agent.capability > 0.5;
   794→          if (behindInRace && agent.alignment > 0.6) {
   795→            weight = 2.0; // Might need to speed up to stay competitive
   796→          } else if (agent.capability < 0.8 && agent.alignment > 0.7) {
   797→            weight = 1.5; // Safe to go faster when well-aligned and low capability
   798→          } else {
   799→            weight = 0.2; // Prefer staying careful
   800→          }
   801→        }
