   806→        weight = agent.alignment * 3 + (agent.hiddenObjective > 0 ? 2 : 0);
   807→        
   808→        // Boost when trust is low (need to rebuild)
   809→        if (getTrustInAI(state.society) < 0.5) { // Phase 2: Use paranoia-derived trust
   810→          weight *= 1.5;
