   816→      case 'destabilize_society':
   817→        // CURRENT RISK: Social manipulation is available NOW at social > 1.5
   818→        // Triggered by EITHER low alignment OR high resentment
   819→        
   820→        // Internal alignment = external alignment - resentment
   821→        // Resentful AIs are internally misaligned even if obedient
   822→        // Phase 5: Use cached trueAlignment
   823→        const internalAlignment = agent.trueAlignment;
